-- GIFs generados para la segunda tanda de calistenia y CrossFit.
UPDATE exercises SET gif_url = CONCAT('/assets/exercises/gifs/', LOWER(REPLACE(name, ' ', '-')), '.gif'), gif_urls = JSON_ARRAY(CONCAT('/assets/exercises/gifs/', LOWER(REPLACE(name, ' ', '-')), '.gif')) WHERE training_type IN ('calisthenics','crossfit') AND name IN ('Pull Up','Muscle Up','Ring Dip','Archer Push Up','Diamond Push Up','Handstand Push Up','Front Lever','Back Lever','Dragon Flag','Toes To Bar','Hanging Knee Raise','Nordic Hamstring Curl','Burpee','Wall Ball','Rowing Machine','Assault Bike','Front Squat','Overhead Squat','Clean And Jerk','Barbell Snatch','Push Press','Sumo Deadlift High Pull','Farmer Carry','Handstand Walk');
